package shopping;import java.sql.*;public class Admin{	String email,pass;	public void setEmail(String email){		this.email=email;	}	public String getEmail(){		return email;	}	public void setPass(String pass){		this.pass=pass;	}	public String getPass(){		return pass;	}	public ResultSet searchAdmin(){		try{			Class.forName("com.mysql.jdbc.Driver");			Connection con=DriverManager.getConnection("jdbc:mysql://localhost/shopping?user=root&password=aarush");			PreparedStatement ps=con.prepareStatement("select * from admin where email=? and pass=?");			ps.setString(1,email);			ps.setString(2,pass);			ResultSet rs=ps.executeQuery();			return rs;		}		catch(Exception e){			System.out.println(e);			return null;		}	}	public String addAdmin(){		try{			Class.forName("com.mysql.jdbc.Driver");			Connection con=DriverManager.getConnection("jdbc:mysql://localhost/shopping?user=root&password=aarush");			PreparedStatement ps=con.prepareStatement("insert into admin values(?,?)");			ps.setString(1,email);			ps.setString(2,pass);			int a=ps.executeUpdate();			if(a==1)				return "New Admin Added.....Successfully !";			else				return "New Admin Not Added";		}		catch(Exception e){			System.out.println(e);			return "Exception : "+e;		}	}}